# Databricks notebook source
# MAGIC %md
# MAGIC # Genie Cost Estimator Agent - one-notebook setup
# MAGIC Builds the complete agent in this workspace in one run:
# MAGIC
# MAGIC | Step | Creates |
# MAGIC |---|---|
# MAGIC | 1 | Schema, and the 10 Lakemeter pricing reference tables from the pricing CSV folder |
# MAGIC | 2 | 29 list-price functions (`estimate_*`, rate lookups), and workload sizing (`size_cluster`, `estimate_sized_workload`, `ref_sizing_*`) |
# MAGIC | 3 | The **DCP Smart Estimation Calculator v4.0.2** as Unity Catalog functions (`dcp_calc`, `dcp_calc_totals`, `dcp_calc_line_items`, `dcp_calc_details`, `dcp_request`) |
# MAGIC | 4 | Rates: `ref_dbu_price_card` (every Lakemeter and sizing DBU price) and `dcp_rate_card` (DCP calculator), both from `system.billing.account_prices` (governed) or `list_prices`; no price = PENDING |
# MAGIC | 5 | `dcp_requests`: named use cases (bundled presets, plus any request JSON files in `requests_path`) |
# MAGIC | 6 | The Genie agent (created, or updated in place when `space_id` is given) |
# MAGIC | 7 | Optional grants for an agent-user group, and a smoke test through the Genie API |
# MAGIC
# MAGIC **Needs:** a UC-enabled cluster (DBR 13.3 LTS+) or serverless; `CREATE SCHEMA/TABLE/FUNCTION` on the catalog;
# MAGIC `SELECT` on `system.billing.account_prices` (or `list_prices`); a Pro or Serverless SQL warehouse for the agent;
# MAGIC the pricing CSVs in a workspace folder (`pricing_data/` from the repo). Re-running is safe: every step is idempotent.

# COMMAND ----------

dbutils.widgets.text("catalog", "", "1. Catalog")
dbutils.widgets.text("schema", "lakemeter", "2. Schema")
dbutils.widgets.text("warehouse_id", "", "3. SQL warehouse id (agent compute)")
dbutils.widgets.text("pricing_path", "", "4. Pricing CSV folder (blank = ./pricing_data)")
dbutils.widgets.dropdown("rate_source", "ACCOUNT_PRICES", ["ACCOUNT_PRICES", "LIST_PRICES"], "5. Databricks rate source (all estimates)")
dbutils.widgets.text("price_regions", "us-east-1", "5b. Regions to price (comma list, or ALL)")
dbutils.widgets.text("requests_path", "", "6. Extra use-case request JSON folder (optional)")
dbutils.widgets.text("space_id", "", "7. Existing Genie agent id to update (blank = create)")
dbutils.widgets.text("space_title", "Lakemeter Cost Estimator", "8. Agent title")
dbutils.widgets.text("user_group", "", "9. Group to grant agent access (optional)")
dbutils.widgets.dropdown("load_pricing_tables", "true", ["true", "false"], "10. Load pricing tables")
dbutils.widgets.dropdown("smoke_test", "true", ["true", "false"], "11. Ask the agent a test question")
W = {k: dbutils.widgets.get(k).strip() for k in ("catalog", "schema", "warehouse_id", "pricing_path", "rate_source", "price_regions", "requests_path",
                                                 "space_id", "space_title", "user_group", "load_pricing_tables", "smoke_test")}
if not W["catalog"] or not W["warehouse_id"]:
    raise ValueError("Set the catalog and warehouse_id widgets.")
FQ = f"{W['catalog']}.{W['schema']}"
ctx = dbutils.notebook.entry_point.getDbutils().notebook().getContext()
HOST = "https://" + spark.conf.get("spark.databricks.workspaceUrl")
HEADERS = {"Authorization": f"Bearer {ctx.apiToken().get()}"}
pricing_path = W["pricing_path"] or "/Workspace" + ctx.notebookPath().get().rsplit("/", 1)[0] + "/pricing_data"
if not pricing_path.startswith("/Workspace") and not pricing_path.startswith("/Volumes"):
    pricing_path = "/Workspace" + pricing_path
import json, os, glob, uuid, time, requests
for k, v in W.items(): print(f"{k:20} {v}")
print(f"{'target':20} {FQ}\n{'pricing_path':20} {pricing_path}")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 1. Schema and pricing reference tables

# COMMAND ----------

spark.sql(f"CREATE SCHEMA IF NOT EXISTS {FQ} COMMENT 'Genie Cost Estimator Agent: pricing data, list-price functions and the DCP calculator'")
TABLES = {"ref_dbu_rates": "dbu-rates.csv", "ref_instance_dbu_rates": "instance-dbu-rates.csv", "ref_dbu_multipliers": "dbu-multipliers.csv",
          "ref_dbsql_rates": "dbsql-rates.csv", "ref_dbsql_warehouse_config": "dbsql-warehouse-config.csv",
          "ref_serverless_rates": "serverless-rates.csv", "ref_sku_region_map": "sku-region-map.csv",
          "ref_fmapi_databricks_rates": "fmapi-databricks-rates.csv", "ref_fmapi_proprietary_rates": "fmapi-proprietary-rates.csv",
          "ref_vm_costs": "vm-costs_part*.csv"}
if W["load_pricing_tables"] == "true":
    scheme = "" if pricing_path.startswith("/Volumes") else "file:"
    for tbl, pattern in TABLES.items():
        df = spark.read.option("header", "true").option("inferSchema", "true").option("mode", "PERMISSIVE").csv(f"{scheme}{pricing_path}/{pattern}")
        df.write.mode("overwrite").option("overwriteSchema", "true").saveAsTable(f"{FQ}.{tbl}")
        print(f"  {tbl:30} {df.count():>8} rows")
else:
    missing = [t for t in TABLES if not spark.catalog.tableExists(f"{FQ}.{t}")]
    if missing: raise ValueError(f"load_pricing_tables=false but these tables are missing: {missing}")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 2. List-price functions and workload sizing
# MAGIC Workload sizing turns a described workload (type, GB per day, runs per day) into a recommended cluster, then prices it
# MAGIC with the list-price functions. Throughput and start-time values in `ref_sizing_profiles` start as planning
# MAGIC assumptions: calibrate them from your job history with `notebooks/11_calibrate_sizing.py`, which can also load the
# MAGIC worker limit and allowed node types from a job cluster policy into `ref_sizing_policy`. Calibrated profiles are kept on re-run.

# COMMAND ----------

FUNCTIONS_SQL = "CREATE OR REPLACE FUNCTION __FQ__.get_instance_dbu_rate(p_cloud STRING, p_instance_type STRING)\nRETURNS DOUBLE\nCOMMENT 'DBU/hour rate for a VM instance type (classic compute sizing).'\nRETURN COALESCE((SELECT dbu_rate FROM __FQ__.ref_instance_dbu_rates\n  WHERE upper(cloud)=upper(p_cloud) AND upper(instance_type)=upper(p_instance_type) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_vm_cost_per_hour(p_cloud STRING, p_region STRING, p_instance_type STRING, p_pricing_tier STRING, p_payment_option STRING)\nRETURNS DOUBLE\nCOMMENT 'Cloud VM $/hour for an instance in a region (on_demand/reserved/spot).'\nRETURN COALESCE((SELECT cost_per_hour FROM __FQ__.ref_vm_costs\n  WHERE upper(cloud)=upper(p_cloud) AND upper(region)=upper(p_region)\n    AND upper(instance_type)=upper(p_instance_type)\n    AND upper(pricing_tier)=upper(p_pricing_tier)\n    AND upper(payment_option)=upper(COALESCE(p_payment_option,'NA')) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_dbu_price(p_cloud STRING, p_region STRING, p_tier STRING, p_product_type STRING)\nRETURNS DOUBLE\nCOMMENT 'Price per DBU (USD) for a product/SKU in a cloud+region+tier.'\nRETURN COALESCE((SELECT price_per_dbu FROM __FQ__.ref_dbu_rates\n  WHERE upper(cloud)=upper(p_cloud) AND upper(region)=upper(p_region) AND upper(tier)=upper(p_tier)\n    AND (upper(sku_name)=upper(p_product_type) OR upper(COALESCE(product_type,''))=upper(p_product_type)) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_photon_multiplier(p_cloud STRING, p_workload_type STRING, p_dlt_edition STRING, p_photon_enabled BOOLEAN, p_serverless_enabled BOOLEAN)\nRETURNS DOUBLE\nCOMMENT 'DBU multiplier applied for Photon/serverless (1.0 if classic no-photon).'\nRETURN CASE\n  WHEN NOT COALESCE(p_photon_enabled,false) AND NOT COALESCE(p_serverless_enabled,false) THEN 1.0\n  ELSE COALESCE((SELECT multiplier FROM __FQ__.ref_dbu_multipliers\n    WHERE upper(cloud)=upper(p_cloud) AND feature='photon'\n      AND upper(sku_type)=upper(CASE upper(p_workload_type)\n        WHEN 'DLT' THEN 'DLT_'||upper(COALESCE(p_dlt_edition,'CORE'))||'_COMPUTE'\n        WHEN 'JOBS' THEN 'JOBS_COMPUTE'\n        WHEN 'ALL_PURPOSE' THEN 'ALL_PURPOSE_COMPUTE'\n        ELSE 'JOBS_COMPUTE' END) LIMIT 1), 1.0)\nEND\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_product_type_for_pricing(p_workload_type STRING, p_serverless_enabled BOOLEAN, p_photon_enabled BOOLEAN, p_dlt_edition STRING, p_dbsql_warehouse_type STRING, p_fmapi_provider STRING)\nRETURNS STRING\nCOMMENT 'Maps a workload config to the DBU pricing SKU name in ref_dbu_rates.'\nRETURN CASE upper(p_workload_type)\n  WHEN 'JOBS' THEN CASE WHEN COALESCE(p_serverless_enabled,false) THEN 'JOBS_SERVERLESS_COMPUTE'\n                        WHEN COALESCE(p_photon_enabled,false) THEN 'JOBS_COMPUTE_(PHOTON)' ELSE 'JOBS_COMPUTE' END\n  WHEN 'ALL_PURPOSE' THEN CASE WHEN COALESCE(p_serverless_enabled,false) THEN 'ALL_PURPOSE_SERVERLESS_COMPUTE'\n                        WHEN COALESCE(p_photon_enabled,false) THEN 'ALL_PURPOSE_COMPUTE_(PHOTON)' ELSE 'ALL_PURPOSE_COMPUTE' END\n  WHEN 'DLT' THEN CASE WHEN COALESCE(p_serverless_enabled,false) THEN 'JOBS_SERVERLESS_COMPUTE'\n                        ELSE 'DLT_'||upper(COALESCE(p_dlt_edition,'CORE'))||'_COMPUTE'||CASE WHEN COALESCE(p_photon_enabled,false) THEN '_(PHOTON)' ELSE '' END END\n  WHEN 'DBSQL' THEN CASE upper(COALESCE(p_dbsql_warehouse_type,'')) WHEN 'SERVERLESS' THEN 'SERVERLESS_SQL_COMPUTE' WHEN 'PRO' THEN 'SQL_PRO_COMPUTE' ELSE 'SQL_COMPUTE' END\n  ELSE upper(p_workload_type)||'_COMPUTE' END\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_hours_per_month(p_workload_type STRING, p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT, p_hours_per_month DOUBLE)\nRETURNS DOUBLE\nCOMMENT 'Monthly runtime hours: explicit hours if given, else runs/day x runtime x days; 24x7 for always-on workloads.'\nRETURN CASE\n  WHEN p_hours_per_month IS NOT NULL THEN p_hours_per_month\n  WHEN upper(p_workload_type) IN ('VECTOR_SEARCH','MODEL_SERVING','LAKEBASE') THEN 24.0*COALESCE(p_days_per_month,30)\n  ELSE COALESCE(p_runs_per_day,0)*(COALESCE(p_avg_runtime_minutes,0)/60.0)*COALESCE(p_days_per_month,30)\nEND\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_classic_compute_dbu(p_cloud STRING, p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT, p_photon_enabled BOOLEAN, p_workload_type STRING, p_dlt_edition STRING)\nRETURNS DOUBLE\nCOMMENT 'DBU/hour for classic JOBS/ALL_PURPOSE/DLT: (driver + worker x N) x photon_multiplier.'\nRETURN (__FQ__.get_instance_dbu_rate(p_cloud,p_driver_node_type)\n       + __FQ__.get_instance_dbu_rate(p_cloud,p_worker_node_type)*COALESCE(p_num_workers,0))\n       * __FQ__.get_photon_multiplier(p_cloud,p_workload_type,p_dlt_edition,p_photon_enabled,false)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_serverless_compute_dbu(p_cloud STRING, p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT, p_workload_type STRING, p_serverless_mode STRING)\nRETURNS DOUBLE\nCOMMENT 'DBU/hour for serverless JOBS/ALL_PURPOSE: base x photon x mode multiplier (ALL_PURPOSE and performance mode = 2x).'\nRETURN (__FQ__.get_instance_dbu_rate(p_cloud,p_driver_node_type)\n       + __FQ__.get_instance_dbu_rate(p_cloud,p_worker_node_type)*COALESCE(p_num_workers,0))\n       * __FQ__.get_photon_multiplier(p_cloud,p_workload_type,NULL,true,true)\n       * CASE WHEN upper(COALESCE(p_workload_type,''))='ALL_PURPOSE' THEN 2.0\n              WHEN lower(COALESCE(p_serverless_mode,'standard'))='performance' THEN 2.0 ELSE 1.0 END\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_dbsql_dbu(p_cloud STRING, p_dbsql_warehouse_type STRING, p_dbsql_warehouse_size STRING, p_dbsql_num_clusters INT)\nRETURNS DOUBLE\nCOMMENT 'DBU/hour for a DBSQL warehouse size x number of clusters.'\nRETURN COALESCE((SELECT dbu_per_hour FROM __FQ__.ref_dbsql_rates\n  WHERE upper(cloud)=upper(p_cloud) AND warehouse_type=lower(p_dbsql_warehouse_type) AND upper(warehouse_size)=upper(p_dbsql_warehouse_size) LIMIT 1), 0)\n  * COALESCE(p_dbsql_num_clusters,1)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_jobs_classic_cost(\n  p_cloud STRING, p_region STRING, p_tier STRING,\n  p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT,\n  p_photon_enabled BOOLEAN, p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost estimate for a classic Lakeflow Jobs (JOBS_COMPUTE) workload. Returns DBU + VM breakdown.'\nRETURN\n  WITH b AS (\n    SELECT __FQ__.calculate_classic_compute_dbu(p_cloud,p_driver_node_type,p_worker_node_type,p_num_workers,p_photon_enabled,'JOBS',NULL) dbu_ph,\n           __FQ__.calculate_hours_per_month('JOBS',p_runs_per_day,p_avg_runtime_minutes,p_days_per_month,NULL) hrs,\n           __FQ__.get_dbu_price(p_cloud,p_region,p_tier,__FQ__.get_product_type_for_pricing('JOBS',false,p_photon_enabled,NULL,NULL,NULL)) price,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_driver_node_type,'on_demand','NA') drv,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_worker_node_type,'on_demand','NA') wrk)\n  SELECT 'JOBS_CLASSIC', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2),\n         round((drv + wrk*COALESCE(p_num_workers,0))*hrs,2),\n         round(dbu_ph*hrs*price + (drv + wrk*COALESCE(p_num_workers,0))*hrs,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_all_purpose_classic_cost(\n  p_cloud STRING, p_region STRING, p_tier STRING,\n  p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT,\n  p_photon_enabled BOOLEAN, p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost estimate for a classic All-Purpose (interactive) compute workload.'\nRETURN\n  WITH b AS (\n    SELECT __FQ__.calculate_classic_compute_dbu(p_cloud,p_driver_node_type,p_worker_node_type,p_num_workers,p_photon_enabled,'ALL_PURPOSE',NULL) dbu_ph,\n           __FQ__.calculate_hours_per_month('ALL_PURPOSE',p_runs_per_day,p_avg_runtime_minutes,p_days_per_month,NULL) hrs,\n           __FQ__.get_dbu_price(p_cloud,p_region,p_tier,__FQ__.get_product_type_for_pricing('ALL_PURPOSE',false,p_photon_enabled,NULL,NULL,NULL)) price,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_driver_node_type,'on_demand','NA') drv,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_worker_node_type,'on_demand','NA') wrk)\n  SELECT 'ALL_PURPOSE_CLASSIC', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2),\n         round((drv + wrk*COALESCE(p_num_workers,0))*hrs,2),\n         round(dbu_ph*hrs*price + (drv + wrk*COALESCE(p_num_workers,0))*hrs,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_dlt_classic_cost(\n  p_cloud STRING, p_region STRING, p_tier STRING, p_dlt_edition STRING,\n  p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT,\n  p_photon_enabled BOOLEAN, p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost estimate for a classic Lakeflow Declarative Pipeline (DLT). p_dlt_edition in CORE/PRO/ADVANCED.'\nRETURN\n  WITH b AS (\n    SELECT __FQ__.calculate_classic_compute_dbu(p_cloud,p_driver_node_type,p_worker_node_type,p_num_workers,p_photon_enabled,'DLT',p_dlt_edition) dbu_ph,\n           __FQ__.calculate_hours_per_month('DLT',p_runs_per_day,p_avg_runtime_minutes,p_days_per_month,NULL) hrs,\n           __FQ__.get_dbu_price(p_cloud,p_region,p_tier,__FQ__.get_product_type_for_pricing('DLT',false,p_photon_enabled,p_dlt_edition,NULL,NULL)) price,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_driver_node_type,'on_demand','NA') drv,\n           __FQ__.get_vm_cost_per_hour(p_cloud,p_region,p_worker_node_type,'on_demand','NA') wrk)\n  SELECT 'DLT_'||upper(COALESCE(p_dlt_edition,'CORE')), dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2),\n         round((drv + wrk*COALESCE(p_num_workers,0))*hrs,2),\n         round(dbu_ph*hrs*price + (drv + wrk*COALESCE(p_num_workers,0))*hrs,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_serverless_compute_cost(\n  p_cloud STRING, p_region STRING, p_tier STRING, p_workload_type STRING,\n  p_driver_node_type STRING, p_worker_node_type STRING, p_num_workers INT, p_serverless_mode STRING,\n  p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost estimate for serverless JOBS or ALL_PURPOSE compute (no separate VM cost; DBU price includes compute).'\nRETURN\n  WITH b AS (\n    SELECT __FQ__.calculate_serverless_compute_dbu(p_cloud,p_driver_node_type,p_worker_node_type,p_num_workers,p_workload_type,p_serverless_mode) dbu_ph,\n           __FQ__.calculate_hours_per_month(p_workload_type,p_runs_per_day,p_avg_runtime_minutes,p_days_per_month,NULL) hrs,\n           __FQ__.get_dbu_price(p_cloud,p_region,p_tier,__FQ__.get_product_type_for_pricing(p_workload_type,true,true,NULL,NULL,NULL)) price)\n  SELECT upper(p_workload_type)||'_SERVERLESS', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2),\n         0.0, round(dbu_ph*hrs*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_dbsql_cost(\n  p_cloud STRING, p_region STRING, p_tier STRING,\n  p_warehouse_type STRING, p_warehouse_size STRING, p_num_clusters INT,\n  p_runs_per_day INT, p_avg_runtime_minutes INT, p_days_per_month INT, p_hours_per_month DOUBLE)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost estimate for a Databricks SQL warehouse. p_warehouse_type in classic/pro/serverless; serverless has no separate VM cost.'\nRETURN\n  WITH whc AS (\n    SELECT driver_instance_type di, worker_instance_type wi, worker_count wc\n    FROM __FQ__.ref_dbsql_warehouse_config\n    WHERE upper(cloud)=upper(p_cloud) AND lower(warehouse_size)=lower(p_warehouse_type) AND upper(warehouse_type)=upper(p_warehouse_size) LIMIT 1),\n  calc AS (\n    SELECT __FQ__.calculate_dbsql_dbu(p_cloud,p_warehouse_type,p_warehouse_size,p_num_clusters) dbu_ph,\n           __FQ__.calculate_hours_per_month('DBSQL',p_runs_per_day,p_avg_runtime_minutes,p_days_per_month,p_hours_per_month) hrs,\n           __FQ__.get_dbu_price(p_cloud,p_region,p_tier,__FQ__.get_product_type_for_pricing('DBSQL',false,false,NULL,p_warehouse_type,NULL)) price,\n           CASE WHEN lower(p_warehouse_type)='serverless' THEN 0.0 ELSE\n             __FQ__.get_vm_cost_per_hour(p_cloud,p_region,whc.di,'on_demand','NA')*COALESCE(p_num_clusters,1)\n             + __FQ__.get_vm_cost_per_hour(p_cloud,p_region,whc.wi,'on_demand','NA')*COALESCE(whc.wc,0)*COALESCE(p_num_clusters,1)\n           END vm_ph\n    FROM (SELECT 1 one) d LEFT JOIN whc ON true)\n  SELECT 'DBSQL_'||upper(p_warehouse_type), dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2),\n         round(vm_ph*hrs,2), round(dbu_ph*hrs*price + vm_ph*hrs,2) FROM calc\n\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_serverless_rate(p_cloud STRING, p_product STRING, p_size_or_model STRING)\nRETURNS DOUBLE\nCOMMENT 'DBU rate from ref_serverless_rates for a product (vector_search/model_serving) and size/model.'\nRETURN COALESCE((SELECT dbu_rate FROM __FQ__.ref_serverless_rates\n  WHERE upper(cloud)=upper(p_cloud) AND lower(product)=lower(p_product) AND upper(size_or_model)=upper(p_size_or_model) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_vector_search_dbu(p_cloud STRING, p_mode STRING, p_capacity_millions DOUBLE)\nRETURNS DOUBLE\nCOMMENT 'Vector Search DBU/hour = rate x CEIL(capacity_millions / divisor); divisor standard=2M, storage_optimized=64M.'\nRETURN __FQ__.get_serverless_rate(p_cloud,'vector_search',p_mode)\n  * ceil(COALESCE(p_capacity_millions,0) / CASE WHEN lower(p_mode)='storage_optimized' THEN 64.0 ELSE 2.0 END)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_model_serving_dbu(p_cloud STRING, p_serverless_size STRING, p_concurrency INT)\nRETURNS DOUBLE\nCOMMENT 'Model Serving DBU/hour = rate x (concurrency for cpu* sizes, else concurrency/4 for GPU).'\nRETURN __FQ__.get_serverless_rate(p_cloud,'model_serving',p_serverless_size)\n  * CASE WHEN lower(COALESCE(p_serverless_size,'cpu')) LIKE 'cpu%' THEN COALESCE(p_concurrency,4) ELSE COALESCE(p_concurrency,4)/4.0 END\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.calculate_lakebase_dbu(p_lakebase_cu INT, p_lakebase_ha_nodes INT)\nRETURNS DOUBLE\nCOMMENT 'Lakebase DBU/hour = capacity_units x HA_nodes.'\nRETURN COALESCE(p_lakebase_cu,0) * COALESCE(p_lakebase_ha_nodes,1)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_fmapi_databricks_dbu(p_cloud STRING, p_model STRING, p_rate_type STRING, p_quantity BIGINT)\nRETURNS DOUBLE\nCOMMENT 'FM API (Databricks-hosted) DBU for a quantity: hourly rate x hours, else (tokens / input_divisor) x rate.'\nRETURN COALESCE((SELECT CASE WHEN COALESCE(is_hourly,false) THEN p_quantity*dbu_rate\n  ELSE (p_quantity / cast(COALESCE(input_divisor,1) as double)) * dbu_rate END\n  FROM __FQ__.ref_fmapi_databricks_rates\n  WHERE upper(cloud)=upper(p_cloud) AND upper(model)=upper(p_model) AND lower(rate_type)=lower(p_rate_type) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_fmapi_proprietary_dbu(p_cloud STRING, p_provider STRING, p_model STRING, p_endpoint_type STRING, p_context_length STRING, p_rate_type STRING, p_quantity BIGINT)\nRETURNS DOUBLE\nCOMMENT 'FM API (proprietary models) DBU for a quantity: hourly rate x hours, else (tokens / input_divisor) x rate.'\nRETURN COALESCE((SELECT CASE WHEN COALESCE(is_hourly,false) THEN p_quantity*dbu_rate\n  ELSE (p_quantity / cast(COALESCE(input_divisor,1) as double)) * dbu_rate END\n  FROM __FQ__.ref_fmapi_proprietary_rates\n  WHERE upper(cloud)=upper(p_cloud) AND upper(provider)=upper(p_provider) AND upper(model)=upper(p_model)\n    AND lower(endpoint_type)=lower(COALESCE(p_endpoint_type,'global')) AND lower(context_length)=lower(COALESCE(p_context_length,'all'))\n    AND lower(rate_type)=lower(p_rate_type) LIMIT 1), 0)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_vector_search_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_mode STRING, p_capacity_millions DOUBLE, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for a Vector Search endpoint (always-on). p_mode in standard/storage_optimized; p_capacity_millions = indexed vectors in millions.'\nRETURN WITH b AS (\n  SELECT __FQ__.calculate_vector_search_dbu(p_cloud,p_mode,p_capacity_millions) dbu_ph,\n         24.0*COALESCE(p_days_per_month,30) hrs,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'VECTOR_SEARCH', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2), 0.0, round(dbu_ph*hrs*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_model_serving_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_serverless_size STRING, p_concurrency INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for a Model Serving endpoint (always-on). p_serverless_size e.g. cpu, gpu_small_t4, gpu_medium_a10g_1x; p_concurrency = provisioned concurrency.'\nRETURN WITH b AS (\n  SELECT __FQ__.calculate_model_serving_dbu(p_cloud,p_serverless_size,p_concurrency) dbu_ph,\n         24.0*COALESCE(p_days_per_month,30) hrs,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'MODEL_SERVING', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2), 0.0, round(dbu_ph*hrs*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_lakebase_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_capacity_units INT, p_ha_nodes INT, p_days_per_month INT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for a Lakebase (managed Postgres) instance (always-on). p_capacity_units = CU, p_ha_nodes = HA node count.'\nRETURN WITH b AS (\n  SELECT __FQ__.calculate_lakebase_dbu(p_capacity_units,p_ha_nodes) dbu_ph,\n         24.0*COALESCE(p_days_per_month,30) hrs,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'DATABASE_SERVERLESS_COMPUTE') price)\n  SELECT 'LAKEBASE', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2), 0.0, round(dbu_ph*hrs*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_databricks_apps_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_app_size STRING, p_num_apps INT, p_hours_per_month DOUBLE)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for Databricks Apps. p_app_size in medium (0.5 DBU/app-hr) or large (1.0); p_hours_per_month default 730.'\nRETURN WITH b AS (\n  SELECT (CASE WHEN lower(p_app_size)='large' THEN 1.0 ELSE 0.5 END)*COALESCE(p_num_apps,1) dbu_ph,\n         COALESCE(p_hours_per_month,730.0) hrs,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'ALL_PURPOSE_SERVERLESS_COMPUTE') price)\n  SELECT 'DATABRICKS_APPS', dbu_ph, hrs, dbu_ph*hrs, price, round(dbu_ph*hrs*price,2), 0.0, round(dbu_ph*hrs*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_fmapi_databricks_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_model STRING, p_rate_type STRING, p_quantity BIGINT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for Databricks-hosted Foundation Model API. p_rate_type e.g. input_token/output_token (p_quantity=tokens) or a provisioned/hourly rate (p_quantity=hours).'\nRETURN WITH b AS (\n  SELECT __FQ__.get_fmapi_databricks_dbu(p_cloud,p_model,p_rate_type,p_quantity) dbu_m,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'FMAPI_DATABRICKS', 0.0, 0.0, dbu_m, price, round(dbu_m*price,2), 0.0, round(dbu_m*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_fmapi_proprietary_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_provider STRING, p_model STRING, p_endpoint_type STRING, p_context_length STRING, p_rate_type STRING, p_quantity BIGINT)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for proprietary-model Foundation Model API. p_provider e.g. anthropic/openai/google; p_quantity=tokens (token rates) or hours (batch_inference).'\nRETURN WITH b AS (\n  SELECT __FQ__.get_fmapi_proprietary_dbu(p_cloud,p_provider,p_model,p_endpoint_type,p_context_length,p_rate_type,p_quantity) dbu_m,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,\n           CASE WHEN upper(p_provider)='GOOGLE' THEN 'GEMINI_MODEL_SERVING' ELSE upper(p_provider)||'_MODEL_SERVING' END) price)\n  SELECT 'FMAPI_PROPRIETARY', 0.0, 0.0, dbu_m, price, round(dbu_m*price,2), 0.0, round(dbu_m*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_ai_parse_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_mode STRING, p_pages_thousands DOUBLE, p_complexity STRING, p_hours_per_month DOUBLE)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for AI Parse (Document AI). p_mode pages: dbu = pages_thousands x complexity rate (low_text 12.5, low_images 22.5, medium 62.5, high 87.5). p_mode dbu: dbu = hours_per_month.'\nRETURN WITH b AS (\n  SELECT CASE WHEN lower(COALESCE(p_mode,'pages'))='dbu' THEN COALESCE(p_hours_per_month,0)\n         ELSE COALESCE(p_pages_thousands,0) * CASE lower(COALESCE(p_complexity,'medium'))\n           WHEN 'low_text' THEN 12.5 WHEN 'low_images' THEN 22.5 WHEN 'high' THEN 87.5 ELSE 62.5 END END dbu_m,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'AI_PARSE', 0.0, 0.0, dbu_m, price, round(dbu_m*price,2), 0.0, round(dbu_m*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_ai_classify_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_document_type STRING, p_num_docs BIGINT, p_custom_rate_per_1000 DOUBLE)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for ai_classify. dbu = (num_docs/1000) x rate; rates short_text 4.5, rental_contract 50; else p_custom_rate_per_1000.'\nRETURN WITH b AS (\n  SELECT (COALESCE(p_num_docs,0)/1000.0) * CASE lower(COALESCE(p_document_type,'custom'))\n           WHEN 'short_text' THEN 4.5 WHEN 'rental_contract' THEN 50.0 ELSE COALESCE(p_custom_rate_per_1000,0) END dbu_m,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'AI_CLASSIFY', 0.0, 0.0, dbu_m, price, round(dbu_m*price,2), 0.0, round(dbu_m*price,2) FROM b\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_ai_extract_cost(p_cloud STRING, p_region STRING, p_tier STRING, p_document_type STRING, p_num_inputs BIGINT, p_custom_rate_per_1000 DOUBLE)\nRETURNS TABLE(workload STRING, dbu_per_hour DOUBLE, hours_per_month DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE, total_cost_per_month DOUBLE)\nCOMMENT 'Monthly cost for ai_extract. dbu = (num_inputs/1000) x rate; rates short_text 45, invoice 45, complex_reasoning 562.5, deep_nesting 537.5; else p_custom_rate_per_1000.'\nRETURN WITH b AS (\n  SELECT (COALESCE(p_num_inputs,0)/1000.0) * CASE lower(COALESCE(p_document_type,'custom'))\n           WHEN 'short_text' THEN 45.0 WHEN 'invoice' THEN 45.0 WHEN 'complex_reasoning' THEN 562.5 WHEN 'deep_nesting' THEN 537.5 ELSE COALESCE(p_custom_rate_per_1000,0) END dbu_m,\n         __FQ__.get_dbu_price(p_cloud,p_region,p_tier,'SERVERLESS_REAL_TIME_INFERENCE') price)\n  SELECT 'AI_EXTRACT', 0.0, 0.0, dbu_m, price, round(dbu_m*price,2), 0.0, round(dbu_m*price,2) FROM b"
stmts = [s.strip() for s in FUNCTIONS_SQL.split("\n-- @@\n") if s.strip()]
for s in stmts: spark.sql(s.replace("__FQ__", FQ))
print(f"{len(stmts)} list-price functions created")
GOV_SQL = "CREATE TABLE IF NOT EXISTS __FQ__.ref_dbu_price_card (\n  cloud STRING, region STRING, tier STRING, product_type STRING, billing_sku STRING, price_per_dbu DOUBLE,\n  status STRING, source STRING, list_price_reference DOUBLE, refreshed_at TIMESTAMP)\nCOMMENT 'Price per DBU used by every Lakemeter estimate_* and sizing function: one row per cloud, region, tier and product. status GOVERNED (system.billing.account_prices), REFERENCE_ONLY (system.billing.list_prices, test workspaces) or PENDING (no single current price - estimates show PENDING, never a fallback). list_price_reference = Lakemeter CSV list price, for comparison only.'\n-- @@\nCREATE OR REPLACE TABLE __FQ__.ref_dbu_price_card\nCOMMENT 'Price per DBU used by every Lakemeter estimate_* and sizing function: one row per cloud, region, tier and product. status GOVERNED (system.billing.account_prices), REFERENCE_ONLY (system.billing.list_prices, test workspaces) or PENDING (no single current price - estimates show PENDING, never a fallback). list_price_reference = Lakemeter CSV list price, for comparison only.'\nAS\nWITH k AS (\n  SELECT upper(cloud) AS cloud, lower(region) AS region, upper(tier) AS tier, upper(sku_name) AS product_type, max(price_per_dbu) AS list_ref\n  FROM __FQ__.ref_dbu_rates\n  WHERE sku_name IS NOT NULL AND region IS NOT NULL AND tier IS NOT NULL AND {{REGION_FILTER}}\n  GROUP BY ALL),\nm AS (\n  SELECT k.*, upper(s.sku_region) AS sku_region\n  FROM k LEFT JOIN (SELECT DISTINCT upper(cloud) AS cloud, lower(region_code) AS region_code, sku_region FROM __FQ__.ref_sku_region_map) s\n    ON s.cloud = k.cloud AND s.region_code = k.region),\np AS (\n  SELECT upper(sku_name) AS sku_name, upper(cloud) AS cloud, CAST({{PRICE_EXPR}} AS DOUBLE) AS price\n  FROM {{RATE_TABLE}}\n  WHERE currency_code = 'USD' AND {{PRICE_EXPR}} IS NOT NULL   -- any usage unit: storage SKUs are priced per GB-month\n    AND price_start_time <= current_timestamp() AND (price_end_time IS NULL OR price_end_time > current_timestamp())),\nc AS (\n  SELECT m.cloud, m.region, m.tier, m.product_type, m.sku_region, m.list_ref,\n         concat(m.tier, '_', m.product_type, '_', coalesce(m.sku_region, '?')) AS reg_sku, concat(m.tier, '_', m.product_type) AS glob_sku,\n         array_distinct(collect_list(pr.price)) AS reg_prices, array_distinct(collect_list(pg.price)) AS glob_prices\n  FROM m\n  LEFT JOIN p pr ON pr.cloud = m.cloud AND pr.sku_name = concat(m.tier, '_', m.product_type, '_', m.sku_region)\n  LEFT JOIN p pg ON pg.cloud = m.cloud AND pg.sku_name = concat(m.tier, '_', m.product_type)\n  GROUP BY ALL),\nd AS (\n  SELECT c.*, CASE WHEN size(reg_prices) > 0 THEN reg_sku ELSE glob_sku END AS billing_sku,\n         CASE WHEN size(reg_prices) > 0 THEN reg_prices ELSE glob_prices END AS prices\n  FROM c)\nSELECT cloud, region, tier, product_type, billing_sku,\n       CASE WHEN size(prices) = 1 THEN prices[0] END AS price_per_dbu,\n       CASE WHEN size(prices) = 1 THEN '{{STATUS}}' ELSE 'PENDING' END AS status,\n       CASE WHEN size(prices) = 1 THEN '{{RATE_TABLE}}'\n            ELSE concat('{{RATE_TABLE}}: ', size(prices), ' current prices for ', billing_sku,\n                        CASE WHEN size(prices) = 0 AND sku_region IS NOT NULL THEN concat(' or ', reg_sku) ELSE '' END, ' (exactly one required)') END AS source,\n       list_ref AS list_price_reference, current_timestamp() AS refreshed_at\nFROM d\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_dbu_price(p_cloud STRING, p_region STRING, p_tier STRING, p_product_type STRING)\nRETURNS DOUBLE\nCOMMENT 'Price per DBU (USD) from ref_dbu_price_card (governed account prices, or list prices in test workspaces). NULL = PENDING: no single current price for that SKU and region - the estimate cost is NULL, never a fallback.'\nRETURN (SELECT price_per_dbu FROM __FQ__.ref_dbu_price_card\n  WHERE cloud = upper(p_cloud) AND region = lower(p_region) AND tier = upper(p_tier) AND product_type = upper(p_product_type)\n  LIMIT 1)\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.get_dbu_price_status(p_cloud STRING, p_region STRING, p_tier STRING, p_product_type STRING)\nRETURNS STRING\nCOMMENT 'Where the DBU price for a SKU comes from: \"<status> <rate>/DBU <billing sku> (<source>)\", or PENDING with the reason.'\nRETURN coalesce(\n  (SELECT CASE WHEN status = 'PENDING' THEN concat('PENDING - ', source)\n               ELSE concat(status, ' $', price_per_dbu, '/DBU ', billing_sku, ' (', source, ')') END\n   FROM __FQ__.ref_dbu_price_card\n   WHERE cloud = upper(p_cloud) AND region = lower(p_region) AND tier = upper(p_tier) AND product_type = upper(p_product_type) LIMIT 1),\n  concat('PENDING - no price-card row for ', upper(p_tier), ' ', upper(p_product_type), ' in ', upper(p_cloud), ' ', lower(p_region),\n         ' (region not loaded into ref_dbu_price_card)'))"
GOV_STMTS = [s.strip() for s in GOV_SQL.split("\n-- @@\n") if s.strip()]
PRICE_CARD_SQL = next(s for s in GOV_STMTS if s.startswith("CREATE OR REPLACE TABLE __FQ__.ref_dbu_price_card"))
for s in GOV_STMTS:
    if s is not PRICE_CARD_SQL: spark.sql(s.replace("__FQ__", FQ))   # price card table + get_dbu_price / get_dbu_price_status (governed)
print("get_dbu_price now reads ref_dbu_price_card (loaded in step 4)")
SIZING_SQL = "CREATE TABLE IF NOT EXISTS __FQ__.ref_sizing_profiles (\n  profile STRING, description STRING, aliases STRING, node_category STRING,\n  gb_per_core_hour_low DOUBLE, gb_per_core_hour_expected DOUBLE, gb_per_core_hour_high DOUBLE,\n  working_set_factor DOUBLE, volume_basis STRING, peak_factor DOUBLE,\n  min_workers INT, preferred_max_workers INT, default_window_minutes INT,\n  startup_minutes INT, min_runtime_minutes INT, always_on BOOLEAN, photon_default BOOLEAN, serverless_ok BOOLEAN,\n  tips STRING, source STRING, calibration_status STRING, calibration_runs INT, calibrated_at TIMESTAMP, calibration_notes STRING)\nCOMMENT 'Workload sizing profiles used by size_cluster / estimate_sized_workload. gb_per_core_hour_low/expected/high: data processed per worker core-hour (low = pessimistic). working_set_factor: GB of cluster memory needed per GB sized (0 = streams through, memory does not bind). volume_basis PER_RUN = daily GB / runs per day; PEAK_HOUR = daily GB / 24 x peak_factor (always-on streaming). default_window_minutes: batch window when the user gives none. calibration_status ASSUMED (planning values) or CALIBRATED (measured by notebook 11 from job history).'\n-- @@\nMERGE INTO __FQ__.ref_sizing_profiles t USING (\n  SELECT * FROM VALUES\n   ('INGESTION', 'Incremental ingestion (Auto Loader / COPY INTO into Delta, scheduled or triggered)',\n    'INGEST,INCREMENTAL_INGESTION,AUTO_LOADER,AUTOLOADER,COPY_INTO,LANDING,BRONZE', 'GENERAL',\n    5.0, 10.0, 20.0, 0.0, 'PER_RUN', 1.0, 1, 32, 60, 5, 5, false, false, true,\n    'Use Auto Loader with availableNow triggers on a schedule; enable optimized writes; serverless jobs avoid cluster start time'),\n   ('ETL', 'ETL / data engineering transformations (joins, aggregations, merges)',\n    'DATA_ENGINEERING,TRANSFORMATION,TRANSFORM,BATCH,BATCH_ETL,SILVER,GOLD,MERGE', 'GENERAL',\n    2.0, 4.0, 8.0, 0.5, 'PER_RUN', 1.0, 2, 32, 120, 5, 10, false, false, true,\n    'Use autoscaling; enable optimized writes; prefer fewer, larger workers for shuffle-heavy joins; i3 / storage-optimized nodes if shuffles spill'),\n   ('STREAMING', 'Always-on streaming / real-time processing',\n    'STREAM,CONTINUOUS_STREAMING,REAL_TIME,REALTIME,KAFKA,KINESIS', 'COMPUTE',\n    5.0, 10.0, 20.0, 0.5, 'PEAK_HOUR', 3.0, 2, 32, 60, 0, 0, true, false, true,\n    'Min 2 workers for availability; autoscale with tight bounds; if minutes of latency are acceptable, a scheduled INGESTION job is far cheaper'),\n   ('ML_TRAINING', 'ML model training',\n    'TRAINING,MODEL_TRAINING,TRAIN,DEEP_LEARNING', 'GPU',\n    0.5, 1.0, 2.0, 4.0, 'PER_RUN', 1.0, 1, 16, 240, 8, 30, false, false, false,\n    'Memory-optimized nodes for classical ML (r5 / E-series); GPU nodes (g5 / NC) for deep learning'),\n   ('ML_INFERENCE', 'Batch scoring / ML inference',\n    'INFERENCE,BATCH_SCORING,SCORING,BATCH_INFERENCE', 'COMPUTE',\n    2.5, 5.0, 10.0, 0.0, 'PER_RUN', 1.0, 2, 32, 60, 5, 10, false, false, true,\n    'Use Model Serving for real-time inference (estimate_model_serving_cost); for batch, partition the input and use mapInPandas')\n  AS v(profile, description, aliases, node_category, gb_per_core_hour_low, gb_per_core_hour_expected, gb_per_core_hour_high,\n       working_set_factor, volume_basis, peak_factor, min_workers, preferred_max_workers, default_window_minutes,\n       startup_minutes, min_runtime_minutes, always_on, photon_default, serverless_ok, tips)) s\nON t.profile = s.profile\nWHEN MATCHED AND coalesce(t.calibration_status, 'ASSUMED') = 'ASSUMED' THEN UPDATE SET\n  description = s.description, aliases = s.aliases, node_category = s.node_category,\n  gb_per_core_hour_low = s.gb_per_core_hour_low, gb_per_core_hour_expected = s.gb_per_core_hour_expected,\n  gb_per_core_hour_high = s.gb_per_core_hour_high, working_set_factor = s.working_set_factor, volume_basis = s.volume_basis,\n  peak_factor = s.peak_factor, min_workers = s.min_workers, preferred_max_workers = s.preferred_max_workers,\n  default_window_minutes = s.default_window_minutes, startup_minutes = s.startup_minutes, min_runtime_minutes = s.min_runtime_minutes,\n  always_on = s.always_on, photon_default = s.photon_default, serverless_ok = s.serverless_ok, tips = s.tips,\n  source = 'Planning assumption', calibration_status = 'ASSUMED'\nWHEN NOT MATCHED THEN INSERT (profile, description, aliases, node_category, gb_per_core_hour_low, gb_per_core_hour_expected,\n  gb_per_core_hour_high, working_set_factor, volume_basis, peak_factor, min_workers, preferred_max_workers, default_window_minutes,\n  startup_minutes, min_runtime_minutes, always_on, photon_default, serverless_ok, tips, source, calibration_status, calibration_runs,\n  calibrated_at, calibration_notes)\nVALUES (s.profile, s.description, s.aliases, s.node_category, s.gb_per_core_hour_low, s.gb_per_core_hour_expected,\n  s.gb_per_core_hour_high, s.working_set_factor, s.volume_basis, s.peak_factor, s.min_workers, s.preferred_max_workers,\n  s.default_window_minutes, s.startup_minutes, s.min_runtime_minutes, s.always_on, s.photon_default, s.serverless_ok, s.tips,\n  'Planning assumption', 'ASSUMED', 0, NULL, NULL)\n-- @@\nCREATE OR REPLACE TABLE __FQ__.ref_sizing_node_families (\n  cloud STRING, node_category STRING, instance_pattern STRING, min_vcpus DOUBLE, notes STRING)\nCOMMENT 'Node families size_cluster may pick from, per cloud and category (regex on instance_type in ref_instance_dbu_rates). Edit to match the customer''s approved instance list; ref_sizing_policy.allowed_node_pattern narrows it further.'\n-- @@\nINSERT INTO __FQ__.ref_sizing_node_families VALUES\n ('AWS', 'GENERAL', '^m5d\\\\.', 4, 'General purpose with local NVMe'),\n ('AWS', 'MEMORY', '^r5d\\\\.', 4, 'Memory optimized with local NVMe'),\n ('AWS', 'COMPUTE', '^c5d\\\\.', 4, 'Compute optimized with local NVMe'),\n ('AWS', 'STORAGE', '^i3\\\\.', 4, 'Storage optimized (shuffle heavy)'),\n ('AWS', 'GPU', '^g5\\\\.', 4, 'NVIDIA A10G'),\n ('AZURE', 'GENERAL', '^Standard_DS[0-9]+_v2$', 4, ''),\n ('AZURE', 'MEMORY', '^Standard_E[0-9]+s_v3$', 4, ''),\n ('AZURE', 'COMPUTE', '^Standard_F[0-9]+s_v2$', 4, ''),\n ('AZURE', 'STORAGE', '^Standard_L[0-9]+s_v2$', 4, ''),\n ('AZURE', 'GPU', '^Standard_NC[0-9]+s_v3$', 4, 'NVIDIA V100'),\n ('GCP', 'GENERAL', '^n2-highmem-[0-9]+$', 4, ''),\n ('GCP', 'MEMORY', '^n2-highmem-[0-9]+$', 4, ''),\n ('GCP', 'COMPUTE', '^c2-standard-[0-9]+$', 4, ''),\n ('GCP', 'STORAGE', '^n2-highmem-[0-9]+$', 4, ''),\n ('GCP', 'GPU', '^a2-highgpu-', 12, '')\n-- @@\nCREATE TABLE IF NOT EXISTS __FQ__.ref_sizing_policy (\n  cloud STRING, max_workers INT, allowed_node_pattern STRING, policy_name STRING, policy_id STRING, source STRING, updated_at TIMESTAMP)\nCOMMENT 'Worker limit and allowed node types for sized clusters, one row per cloud. Load from the customer''s job cluster policy with notebook 11 (source = cluster policy). The default row is a planning guardrail, not a Databricks limit.'\n-- @@\nMERGE INTO __FQ__.ref_sizing_policy t\nUSING (SELECT * FROM VALUES ('AWS'), ('AZURE'), ('GCP') AS v(cloud)) s ON t.cloud = s.cloud\nWHEN NOT MATCHED THEN INSERT (cloud, max_workers, allowed_node_pattern, policy_name, policy_id, source, updated_at)\nVALUES (s.cloud, 100, NULL, 'Default guardrail', NULL, 'default guardrail - load the job cluster policy with notebook 11', current_timestamp())\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.size_cluster(\n  p_workload STRING, p_data_gb DOUBLE, p_runs_per_day INT DEFAULT 1, p_window_minutes INT DEFAULT NULL,\n  p_cloud STRING DEFAULT 'AWS', p_node_type STRING DEFAULT NULL, p_max_workers INT DEFAULT NULL, p_region STRING DEFAULT NULL)\nRETURNS TABLE(workload_profile STRING, description STRING, data_gb_per_day DOUBLE, runs_per_day INT, sizing_gb DOUBLE,\n  window_minutes INT, node_type STRING, driver_node_type STRING, num_workers INT, autoscale_min_workers INT, autoscale_max_workers INT,\n  vcpus_per_node DOUBLE, memory_gb_per_node DOUBLE, total_worker_vcpus DOUBLE, total_worker_memory_gb DOUBLE, dbu_per_hour DOUBLE,\n  required_cores DOUBLE, required_memory_gb DOUBLE, workers_needed INT, max_workers_allowed INT, max_workers_source STRING,\n  limiting_factor STRING, status STRING, runtime_minutes_low INT, runtime_minutes_expected INT, runtime_minutes_high INT,\n  workers_low INT, workers_high INT, parallel_jobs_needed INT,\n  serverless_workers_low INT, serverless_workers_expected INT, serverless_workers_high INT,\n  serverless_runtime_minutes_low INT, serverless_runtime_minutes_expected INT, serverless_runtime_minutes_high INT,\n  startup_minutes INT, always_on BOOLEAN, photon_recommended BOOLEAN, serverless_ok BOOLEAN, shuffle_partitions INT,\n  gb_per_core_hour_low DOUBLE, gb_per_core_hour_expected DOUBLE, gb_per_core_hour_high DOUBLE, throughput_basis STRING,\n  options STRING, assumptions STRING, tips STRING)\nCOMMENT 'Recommend a classic job cluster for a described workload when the user does not know the cluster size. p_workload: INGESTION, ETL, STREAMING (always-on), ML_TRAINING, ML_INFERENCE (or an alias). p_data_gb: GB processed per day (ML_TRAINING: per run). p_window_minutes: time each run may take (default per profile). Sized on EXPECTED throughput so each run fits the window; runtime_minutes_low/expected/high give the range on that cluster. status FITS_WINDOW or EXCEEDS_WINDOW / EXCEEDS_POLICY (then read options). Worker limit from ref_sizing_policy. No rows = unknown workload type or no data volume.'\nRETURN\n  WITH i AS (\n    SELECT CASE WHEN upper(trim(p_workload)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE upper(regexp_replace(trim(p_workload), '[ -]+', '_')) END AS w,\n           p_data_gb AS gb, greatest(coalesce(p_runs_per_day, 1), 1) AS rpd, p_window_minutes AS win_in, p_max_workers AS maxw_in,\n           coalesce(CASE WHEN upper(trim(p_cloud)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE upper(trim(p_cloud)) END, 'AWS') AS cl,\n           CASE WHEN upper(trim(p_node_type)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE trim(p_node_type) END AS node,\n           CASE WHEN upper(trim(p_region)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE lower(trim(p_region)) END AS rg),\n  p AS (\n    SELECT s.*, i.*,\n           CASE WHEN s.volume_basis = 'PEAK_HOUR' THEN i.gb / 24.0 * s.peak_factor ELSE i.gb / i.rpd END AS sgb,\n           CASE WHEN s.always_on THEN 60 ELSE greatest(coalesce(i.win_in, s.default_window_minutes), s.startup_minutes + 1) END AS win,\n           greatest(coalesce(i.maxw_in, pol.max_workers, 100), 1) AS pmax,\n           CASE WHEN i.maxw_in IS NOT NULL THEN 'given by the user' ELSE coalesce(pol.source, 'default guardrail') END AS pmax_src,\n           pol.allowed_node_pattern AS allow_pat\n    FROM i JOIN __FQ__.ref_sizing_profiles s ON i.w = s.profile OR array_contains(split(s.aliases, ','), i.w)\n    LEFT JOIN __FQ__.ref_sizing_policy pol ON pol.cloud = i.cl\n    WHERE i.gb IS NOT NULL AND i.gb > 0),\n  q AS (\n    SELECT p.*, greatest(win - startup_minutes, 1) / 60.0 AS eff_h, sgb * working_set_factor AS req_mem FROM p),\n  c AS (\n    SELECT q.*, d.instance_type, d.vcpus, d.memory_gb, d.dbu_rate,\n           q.sgb / (q.gb_per_core_hour_expected * q.eff_h) AS req_cores,\n           cast(ceil(q.sgb / (q.gb_per_core_hour_expected * q.eff_h) / d.vcpus) AS INT) AS n_cpu,\n           cast(ceil(q.req_mem / d.memory_gb) AS INT) AS n_mem\n    FROM q JOIN __FQ__.ref_instance_dbu_rates d ON upper(d.cloud) = q.cl AND d.is_active\n    WHERE (q.node IS NOT NULL AND lower(d.instance_type) = lower(q.node))\n       OR (q.node IS NULL\n           AND EXISTS (SELECT 1 FROM __FQ__.ref_sizing_node_families f\n                       WHERE f.cloud = q.cl AND f.node_category = q.node_category\n                         AND d.instance_type RLIKE f.instance_pattern AND d.vcpus >= f.min_vcpus)\n           AND (q.allow_pat IS NULL OR d.instance_type RLIKE q.allow_pat)\n           AND (q.rg IS NULL OR EXISTS (SELECT 1 FROM __FQ__.ref_vm_costs v\n                                        WHERE upper(v.cloud) = q.cl AND lower(v.region) = q.rg\n                                          AND v.instance_type = d.instance_type AND lower(v.pricing_tier) = 'on_demand')))),\n  n AS (SELECT c.*, greatest(min_workers, n_cpu, n_mem) AS need FROM c),\n  best AS (\n    SELECT n.*, least(need, pmax) AS wk FROM n\n    ORDER BY CASE WHEN need <= least(preferred_max_workers, pmax) THEN 0 WHEN need <= pmax THEN 1 ELSE 2 END,\n             CASE WHEN need <= pmax THEN vcpus ELSE -vcpus END, dbu_rate\n    LIMIT 1),\n  r AS (\n    SELECT b.*,\n           CASE WHEN always_on THEN 1440 ELSE cast(ceil(startup_minutes + greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_high * wk * vcpus))) AS INT) END AS rt_l,\n           CASE WHEN always_on THEN 1440 ELSE cast(ceil(startup_minutes + greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_expected * wk * vcpus))) AS INT) END AS rt_e,\n           CASE WHEN always_on THEN 1440 ELSE cast(ceil(startup_minutes + greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_low * wk * vcpus))) AS INT) END AS rt_h,\n           CASE WHEN always_on THEN least(pmax, greatest(min_workers, cast(ceil(sgb / gb_per_core_hour_high / vcpus) AS INT), n_mem)) ELSE wk END AS wk_l,\n           CASE WHEN always_on THEN least(pmax, greatest(min_workers, cast(ceil(sgb / gb_per_core_hour_low / vcpus) AS INT), n_mem)) ELSE wk END AS wk_h,\n           CASE WHEN always_on THEN greatest(min_workers, cast(ceil(sgb / gb_per_core_hour_high / vcpus) AS INT), n_mem) ELSE need END AS sw_l,\n           CASE WHEN always_on THEN greatest(min_workers, cast(ceil(sgb / gb_per_core_hour_low / vcpus) AS INT), n_mem) ELSE need END AS sw_h\n    FROM best b)\n  SELECT profile, description, gb, rpd, round(sgb, 3), CASE WHEN always_on THEN NULL ELSE win END,\n         instance_type, instance_type, wk, least(min_workers, wk), least(pmax, greatest(wk, wk_h)),\n         vcpus, memory_gb, wk * vcpus, wk * memory_gb, round(dbu_rate * (wk + 1), 4),\n         round(req_cores, 2), round(req_mem, 2), need, pmax, pmax_src,\n         CASE WHEN need > pmax THEN 'POLICY_CAP'\n              WHEN need = min_workers AND n_cpu < min_workers AND n_mem < min_workers THEN 'MIN_WORKERS'\n              WHEN n_mem > n_cpu THEN 'MEMORY' ELSE 'CORES' END,\n         CASE WHEN need > pmax THEN CASE WHEN always_on THEN 'EXCEEDS_POLICY' ELSE 'EXCEEDS_WINDOW' END\n              WHEN NOT always_on AND rt_e > win THEN 'EXCEEDS_WINDOW' ELSE 'FITS_WINDOW' END,\n         rt_l, rt_e, rt_h, wk_l, wk_h,\n         cast(ceil(need / pmax) AS INT),\n         sw_l, need, sw_h,\n         CASE WHEN always_on THEN 1440 ELSE cast(ceil(greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_high * sw_l * vcpus))) AS INT) END,\n         CASE WHEN always_on THEN 1440 ELSE cast(ceil(greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_expected * need * vcpus))) AS INT) END,\n         CASE WHEN always_on THEN 1440 ELSE cast(ceil(greatest(min_runtime_minutes, 60.0 * sgb / (gb_per_core_hour_low * sw_h * vcpus))) AS INT) END,\n         startup_minutes, always_on, photon_default, serverless_ok,\n         cast(greatest(wk * vcpus * 2, 200) AS INT),\n         gb_per_core_hour_low, gb_per_core_hour_expected, gb_per_core_hour_high,\n         CASE WHEN calibration_status = 'CALIBRATED'\n              THEN concat('CALIBRATED from ', calibration_runs, ' job runs (', date_format(calibrated_at, 'yyyy-MM-dd'), ')')\n              ELSE 'ASSUMED planning values (not yet calibrated with job history)' END,\n         CASE WHEN need > pmax AND NOT always_on THEN concat(\n                'Needs ', need, ' x ', instance_type, ' workers to finish in ', win, ' min but the worker limit is ', pmax, ' (', pmax_src, '). Options: ',\n                '(1) run on the ', wk, '-worker cluster, about ', rt_e, ' min per run; ',\n                '(2) split into ', cast(ceil(need / pmax) AS INT), ' parallel jobs of up to ', pmax, ' workers each; ',\n                '(3) serverless jobs (no worker limit)', CASE WHEN serverless_ok THEN '' ELSE ' - not suited to this workload type' END, '; ',\n                '(4) ask for a higher worker limit.')\n              WHEN need > pmax THEN concat('Needs ', need, ' workers to keep up but the worker limit is ', pmax, ' (', pmax_src, '): split the stream or raise the limit.')\n              WHEN NOT always_on AND rt_e > win THEN concat('The minimum runtime (', rt_e, ' min incl. ', startup_minutes, ' min cluster start) is longer than the ', win, '-minute window.')\n              ELSE NULL END,\n         concat('Planning estimate - validate with a test run. Sized on ', round(sgb, 2), ' GB',\n                CASE WHEN volume_basis = 'PEAK_HOUR' THEN concat(' in the peak hour (daily GB / 24 x ', peak_factor, ')') ELSE ' per run' END,\n                CASE WHEN always_on THEN ', always on 24 x 7' ELSE concat(' to finish within ', win, ' min') END,\n                '; throughput ', gb_per_core_hour_low, ' / ', gb_per_core_hour_expected, ' / ', gb_per_core_hour_high, ' GB per core-hour (low / expected / high)',\n                CASE WHEN working_set_factor > 0 THEN concat('; memory ', working_set_factor, ' GB per GB sized') ELSE '; memory not a constraint (data streams through)' END,\n                CASE WHEN always_on THEN '' ELSE concat('; ', startup_minutes, ' min cluster start, min ', min_runtime_minutes, ' min runtime') END,\n                '; worker limit ', pmax, ' (', pmax_src, ')',\n                CASE WHEN node IS NOT NULL THEN concat('; node type ', instance_type, ' given by the user') ELSE concat('; smallest ', lower(node_category), ' node that fits') END,\n                '. Throughput ', CASE WHEN calibration_status = 'CALIBRATED' THEN concat('calibrated from ', calibration_runs, ' job runs') ELSE 'values are assumed' END, '.'),\n         tips\n  FROM r\n-- @@\nCREATE OR REPLACE FUNCTION __FQ__.estimate_sized_workload(\n  p_workload STRING, p_data_gb DOUBLE, p_runs_per_day INT DEFAULT 1, p_days_per_month INT DEFAULT 30,\n  p_window_minutes INT DEFAULT NULL, p_cloud STRING DEFAULT 'AWS', p_region STRING DEFAULT 'us-east-1', p_tier STRING DEFAULT 'ENTERPRISE',\n  p_node_type STRING DEFAULT NULL, p_photon_enabled BOOLEAN DEFAULT NULL, p_max_workers INT DEFAULT NULL)\nRETURNS TABLE(compute_option STRING, scenario STRING, workload_profile STRING, node_type STRING, num_workers INT, photon_enabled BOOLEAN,\n  runtime_minutes_per_run INT, runs_per_day INT, days_per_month INT, hours_per_month DOUBLE,\n  dbu_per_hour DOUBLE, dbu_per_month DOUBLE, dbu_price DOUBLE, dbu_cost_per_month DOUBLE, vm_cost_per_month DOUBLE,\n  total_cost_per_month DOUBLE, status STRING, window_minutes INT, throughput_basis STRING, options STRING, price_basis STRING, sizing_basis STRING)\nCOMMENT 'Size a cluster for a described workload (size_cluster) and price it with the Lakemeter functions (DBU price from ref_dbu_price_card; NULL cost = PENDING price). Rows: compute_option JOBS_CLASSIC (DBU + VM on the recommended cluster) and JOBS_SERVERLESS (no worker limit, no cluster start), each for scenario LOW / EXPECTED / HIGH (throughput range). Use when the user describes data volume and frequency but no cluster. p_data_gb = GB per day. Weekly: p_runs_per_day 1, p_days_per_month 4. p_window_minutes = time each run may take.'\nRETURN\n  WITH a AS (\n    SELECT coalesce(CASE WHEN upper(trim(p_cloud)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE upper(trim(p_cloud)) END, 'AWS') AS cl,\n           coalesce(CASE WHEN upper(trim(p_region)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE lower(trim(p_region)) END, 'us-east-1') AS rg,\n           coalesce(CASE WHEN upper(trim(p_tier)) IN ('', 'NULL', 'NONE', 'N/A') THEN NULL ELSE upper(trim(p_tier)) END, 'ENTERPRISE') AS tr,\n           p_workload AS w, p_data_gb AS gb, p_runs_per_day AS rpd_in, p_window_minutes AS win_in, p_node_type AS node_in,\n           p_max_workers AS maxw_in, p_photon_enabled AS ph_in, coalesce(p_days_per_month, 30) AS dpm),\n  s AS (\n    SELECT z.*, a.cl, a.rg, a.tr, a.dpm, coalesce(a.ph_in, z.photon_recommended) AS ph,\n           CASE WHEN z.always_on THEN 1 ELSE z.runs_per_day END AS rpd\n    FROM a, LATERAL __FQ__.size_cluster(a.w, a.gb, a.rpd_in, a.win_in, a.cl, a.node_in, a.maxw_in, a.rg) z),\n  k AS (\n    SELECT s.*, x.scenario,\n           CASE x.scenario WHEN 'LOW' THEN s.workers_low WHEN 'HIGH' THEN s.workers_high ELSE s.num_workers END AS cw,\n           CASE x.scenario WHEN 'LOW' THEN s.runtime_minutes_low WHEN 'HIGH' THEN s.runtime_minutes_high ELSE s.runtime_minutes_expected END AS crt,\n           CASE x.scenario WHEN 'LOW' THEN s.serverless_workers_low WHEN 'HIGH' THEN s.serverless_workers_high ELSE s.serverless_workers_expected END AS sw,\n           CASE x.scenario WHEN 'LOW' THEN s.serverless_runtime_minutes_low WHEN 'HIGH' THEN s.serverless_runtime_minutes_high ELSE s.serverless_runtime_minutes_expected END AS srt\n    FROM s, (SELECT * FROM VALUES ('LOW'), ('EXPECTED'), ('HIGH') AS v(scenario)) x)\n  SELECT 'JOBS_CLASSIC', k.scenario, k.workload_profile, k.node_type, k.cw, k.ph, k.crt, k.rpd, k.dpm, e.hours_per_month,\n         e.dbu_per_hour, e.dbu_per_month, e.dbu_price, e.dbu_cost_per_month, e.vm_cost_per_month, e.total_cost_per_month,\n         CASE WHEN k.always_on THEN k.status WHEN k.crt <= k.window_minutes THEN 'FITS_WINDOW' ELSE 'EXCEEDS_WINDOW' END,\n         k.window_minutes, k.throughput_basis, k.options,\n         concat('DBU price: ', __FQ__.get_dbu_price_status(k.cl, k.rg, k.tr, __FQ__.get_product_type_for_pricing('JOBS', false, k.ph, NULL, NULL, NULL)),\n                '; VM: cloud on-demand list price (ref_vm_costs)'), k.assumptions\n  FROM k, LATERAL __FQ__.estimate_jobs_classic_cost(k.cl, k.rg, k.tr, k.node_type, k.node_type, k.cw, k.ph, k.rpd, k.crt, k.dpm) e\n  UNION ALL\n  SELECT 'JOBS_SERVERLESS', k.scenario, k.workload_profile, concat('serverless (sized as ', k.sw, ' x ', k.node_type, ')'), k.sw, true,\n         k.srt, k.rpd, k.dpm, e.hours_per_month,\n         e.dbu_per_hour, e.dbu_per_month, e.dbu_price, e.dbu_cost_per_month, e.vm_cost_per_month, e.total_cost_per_month,\n         CASE WHEN k.always_on OR k.srt <= k.window_minutes THEN 'FITS_WINDOW' ELSE 'EXCEEDS_WINDOW' END, k.window_minutes, k.throughput_basis, NULL,\n         concat('DBU price: ', __FQ__.get_dbu_price_status(k.cl, k.rg, k.tr, __FQ__.get_product_type_for_pricing('JOBS', true, true, NULL, NULL, NULL))), concat(k.assumptions, ' Serverless: sized to fit the window with no worker limit; no cluster start billed.')\n  FROM k, LATERAL __FQ__.estimate_serverless_compute_cost(k.cl, k.rg, k.tr, 'JOBS', k.node_type, k.node_type, k.sw, 'standard', k.rpd, k.srt, k.dpm) e\n  WHERE k.serverless_ok"
if spark.catalog.tableExists(f"{FQ}.ref_sizing_profiles") and "gb_per_core_hour_expected" not in spark.table(f"{FQ}.ref_sizing_profiles").columns:
    spark.sql(f"DROP TABLE {FQ}.ref_sizing_profiles")   # pre-v2 sizing table (no throughput range): rebuild
for s in [s.strip() for s in SIZING_SQL.split("\n-- @@\n") if s.strip()]:
    spark.sql(s.replace("__FQ__", FQ))
print("Workload sizing created: ref_sizing_profiles, ref_sizing_node_families, size_cluster, estimate_sized_workload")

